// Emoji sequences in text, per Unicode UTS #51: which code points form one emoji (keycaps, flags,
// tag flags, skin tones, ZWJ sequences, presentation selectors) and the key of its picture in the
// emoji pack (resources/emoji). Properties come from Unicode's emoji-data.txt
// (EmojiData.inc, generated by scripts/emoji/build_emoji_pack.py).
#pragma once

#include <cstddef>
#include <string>
#include <string_view>
#include <vector>

namespace enp::model::emoji {

// The emoji sequence that starts at text[pos]: its length in bytes, and in `*key` the picture's
// key (lower-case hex code points of at least 4 digits joined by '_', without U+FE0F, e.g. "2b07",
// "1f469_200d_1f52c", "0023_20e3"). 0 when no emoji starts there: plain text, a character whose
// default is text (⬇ without U+FE0F, digits, ©) or one asked to be text with U+FE0E.
size_t match(std::string_view text, size_t pos, std::string* key);

// A code point that never shows on its own at text[pos] (variation selectors 15 and 16, a joiner
// or tag outside a sequence, the keycap combiner alone): its length in bytes, else 0.
size_t invisible(std::string_view text, size_t pos);

// A ZWJ sequence's parts (keys), for when the whole has no picture: drawn side by side.
std::vector<std::string> components(const std::string& key);
// The key without skin-tone modifiers ("1f44d_1f3fd" -> "1f44d"), for when the toned one is missing.
std::string withoutModifiers(const std::string& key);

// The Unicode version the properties come from.
const char* unicodeVersion();

} // namespace enp::model::emoji
